import java.util.*; public class TrafficSignalStreakAnalyzer{static void findLongestStreak(String s){if(s.isEmpty())return;char b=s.charAt(0),c=b;int l=1,bl=1;for(int i=1;i<s.length();i++){if(s.charAt(i)==c)l++;else{c=s.charAt(i);l=1;}if(l>bl){bl=l;b=c;}}System.out.println("Longest Streak: '"+b+"' repeated "+bl+" times");}public static void main(String[] z){findLongestStreak(new Scanner(System.in).nextLine());}}